sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        // Clear field if student is cleared
        if (newValue === '') {
            g_form.setValue('register_number', '');
        }
        return;
    }

    // Get the referenced Student Profile record asynchronously
    g_form.getReference('student', function(studentGr) {
        if (studentGr && studentGr.registration_number) {
            g_form.setValue('register_number', studentGr.registration_number);
        } else {
            g_form.setValue('register_number', '');
        }
    });
}
